Vamos juntar tudo em um exemplo resolvido, com comentários explicando o porquê de cada passo. São duas funções: uma para gerar o hash no cadastro e outra para conferir no login.

```js
import { scryptSync, randomBytes, timingSafeEqual } from 'node:crypto';

// Cadastro: transforma a senha em hash antes de guardar.
function gerarHash(senha) {
  // 1. Cria um sal aleatório de 16 bytes. Sem sal, senhas iguais
  //    gerariam hashes iguais — e o atacante perceberia.
  const sal = randomBytes(16).toString('hex');

  // 2. Mistura a senha com o sal e aplica scrypt (lento de propósito).
  const hash = scryptSync(senha, sal, 64).toString('hex');

  // 3. Devolve sal e hash juntos, separados por ':'. Os dois são
  //    necessários na hora de conferir, então guardamos os dois.
  return sal + ':' + hash;
}

// Login: confere se a senha digitada bate com o hash guardado.
function conferirSenha(senha, hashGuardado) {
  // 1. Separa o sal do hash dentro do valor guardado.
  const partes = hashGuardado.split(':');
  if (partes.length !== 2) return false;

  const sal = partes[0];
  const hashEsperado = Buffer.from(partes[1], 'hex');

  // 2. Recalcula o hash com o MESMO sal.
  const hashDaTentativa = scryptSync(senha, sal, 64);

  // 3. Compara os dois hashes com timingSafeEqual — seguro contra
  //    ataques de tempo. Se os tamanhos diferem, devolve false logo.
  if (hashEsperado.length !== hashDaTentativa.length) return false;
  return timingSafeEqual(hashEsperado, hashDaTentativa);
}

const hashGuardado = gerarHash('cavalo-bala-42'); // vai para o banco
console.log(conferirSenha('cavalo-bala-42', hashGuardado)); // true
console.log(conferirSenha('senha-errada', hashGuardado)); // false
```

Repare: em lugar nenhum a senha original aparece no banco. Só o hash. É assim que os sistemas de verdade funcionam.
